  const [ngoApplications, setNgoApplications] = useState(() => JSON.parse(localStorage.getItem("wastelytics-ngo-apps") || "null") || []);
  const [showLogin, setShowLogin] = useState(false);
  const [signupRole, setSignupRole] = useState(null);
  const [form, setForm] = useState({ item: "", category: "Mains", qty: "", reason: "Overproduction", useBy: "", expiryStatus: "Fresh", storage: "Refrigerated", foodType: "Vegetarian", pickupTime: "20:30", packaging: "Sealed & labelled", photo: "" });
  const t = copy[lang];
  useEffect(() => { document.body.className = dark ? "dark" : ""; localStorage.setItem("wastelytics-theme", dark ? "dark" : "light"); }, [dark]);
  useEffect(() => { localStorage.setItem("wastelytics-lang", lang); localStorage.setItem("wastelytics-logs", JSON.stringify(logs)); }, [lang, logs]);
  useEffect(() => { localStorage.setItem("wastelytics-orgs", JSON.stringify(orgs)); localStorage.setItem("wastelytics-orgmeta", JSON.stringify(orgMeta)); localStorage.setItem("wastelytics-ngo-apps", JSON.stringify(ngoApplications)); }, [orgs, orgMeta, ngoApplications]);
  const totalKg = logs.reduce((a, b) => a + Number(b.qty), 0);
